package com.novelarrow.reader.playback.local

import java.io.File
import java.io.FileOutputStream
import java.nio.ByteBuffer
import java.nio.ByteOrder

/**
 * Encapsulates raw PCM audio generated by the local TTS engine.
 *
 * @property samples Normalized float audio samples in the range [-1.0, 1.0].
 * @property sampleRate Sampling frequency in Hz (e.g., 22050 Hz or 16000 Hz).
 * @property channelCount Number of audio channels (1 for Mono).
 */
data class AudioData(
    val samples: FloatArray,
    val sampleRate: Int,
    val channelCount: Int = 1
) {
    /** Audio duration in seconds. */
    val durationSeconds: Float
        get() = if (sampleRate > 0) samples.size.toFloat() / sampleRate else 0f

    /** Audio duration in milliseconds. */
    val durationMs: Long
        get() = (durationSeconds * 1000).toLong()

    /**
     * Converts normalized 32-bit float samples [-1.0, 1.0] to signed 16-bit PCM shorts.
     */
    fun toShortPcm(): ShortArray {
        val shorts = ShortArray(samples.size)
        for (i in samples.indices) {
            val clamped = samples[i].coerceIn(-1.0f, 1.0f)
            shorts[i] = (clamped * 32767.0f).toInt().toShort()
        }
        return shorts
    }

    /**
     * Converts audio samples to raw little-endian 16-bit PCM byte array.
     */
    fun toPcm16Bytes(): ByteArray {
        val shorts = toShortPcm()
        val bytes = ByteArray(shorts.size * 2)
        val buffer = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN)
        for (sample in shorts) {
            buffer.putShort(sample)
        }
        return bytes
    }

    /**
     * Writes audio data as a standard PCM WAV file (16-bit Little-Endian Mono).
     */
    fun saveAsWav(outputFile: File) {
        val pcmBytes = toPcm16Bytes()
        val totalAudioLen = pcmBytes.size.toLong()
        val totalDataLen = totalAudioLen + 36
        val byteRate = (sampleRate * channelCount * 2).toLong()

        outputFile.parentFile?.mkdirs()
        FileOutputStream(outputFile).use { out ->
            val header = ByteArray(44)
            val bb = ByteBuffer.wrap(header).order(ByteOrder.LITTLE_ENDIAN)

            // RIFF header
            bb.put('R'.code.toByte()).put('I'.code.toByte()).put('F'.code.toByte()).put('F'.code.toByte())
            bb.putInt((totalDataLen and 0xffffffffL).toInt())
            bb.put('W'.code.toByte()).put('A'.code.toByte()).put('V'.code.toByte()).put('E'.code.toByte())

            // fmt subchunk
            bb.put('f'.code.toByte()).put('m'.code.toByte()).put('t'.code.toByte()).put(' '.code.toByte())
            bb.putInt(16) // Subchunk1Size for PCM
            bb.putShort(1.toShort()) // AudioFormat 1 = PCM
            bb.putShort(channelCount.toShort())
            bb.putInt(sampleRate)
            bb.putInt(byteRate.toInt())
            bb.putShort((channelCount * 2).toShort()) // block align
            bb.putShort(16.toShort()) // bits per sample

            // data subchunk
            bb.put('d'.code.toByte()).put('a'.code.toByte()).put('t'.code.toByte()).put('a'.code.toByte())
            bb.putInt((totalAudioLen and 0xffffffffL).toInt())

            out.write(header)
            out.write(pcmBytes)
            out.flush()
        }
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is AudioData) return false
        return sampleRate == other.sampleRate &&
                channelCount == other.channelCount &&
                samples.contentEquals(other.samples)
    }

    override fun hashCode(): Int {
        var result = samples.contentHashCode()
        result = 31 * result + sampleRate
        result = 31 * result + channelCount
        return result
    }
}
